/**
 * 乾隆大藏经·唯一数据真源（经表 + 卷表合并）
 *
 * 字段说明（按数组顺序）：
 *   0: sutra       - 经号。末行《勘误表》为非数字经号（""）：无卷表、目录页
 *                    不显编号、不生成卷索引链接，仅提供阅读入口（169册 1~62页）。
 *                    这是结构必需的特殊记录类型，不是数据错误。
 *   1: start       - 起始页码 (格式: "册-页")
 *   2: end         - 结束页码 (格式: "册-页")
 *   3: title       - 经名（含卷数，简体为主）
 *   4: translator  - 译者
 *   5: alias       - 别名 (亦名/一名，可选；无则缺省)
 *   6: tradTitle   - 繁体经名（卷索引页 h1 用，可选；无则缺省）
 *   7: rolls       - 卷列表 [{ t,i,b? }]（所有经都有；单卷经=[{t:函号,i:start6}]；
 *                    b=加黑子串，全库仅经1165 的4条「xx菩萨造/释」使用）
 *   8: gs          - 人工分组标记（仅经1165，可选）
 *
 * 分类映射说明：
 *   key: 该分类第一本经的 sutra 编号
 *   value: 分类名称
 *
 * 使用方式（构建期）：
 *   import { sutraLinks, categoryMap, VOLUME_PAGE_COUNTS } from './data/sutra_table.js'
 *
 * 浏览器端不直接加载本文件；运行时使用 data/cache/ 下的派生切片（由 gen_cache.mjs 生成）
 */
